Consider introducing checks for `msg.sender` to ensure the recipient of the money is as intended.","rule":"eth-send-unchecked-address","severity":"High"}],"code":[{"path":"src/Vault.sol","source":"    function withdraw(uint256 amount) external {
        if (amount == 0) revert ZeroAmount();
        uint256 available = balanceOf[msg.sender];
        if (amount > available) revert InsufficientBalance(amount, available);

        (bool sent,) = msg.sender.call{value: amount}("");
        if (!sent) revert TransferFailed();

        balanceOf[msg.sender] = available - amount;
        totalDeposits -= amount;
        emit Withdrawn(msg.sender, amount);
    }"}]}}
